cd /Users/a77/.finance-runtime/reviews/nightly-deploy-execute-20260921/spec-tree && for f in intelligence/dream/com.financeworkspace.daily-full-review-sync.plist intelligence/dream/com.financeworkspace.daily-full-review-finalize.plist; do echo "=== $f ==="; git show f783f19c8a01fbe8d0ed70d851df7ed14598c051:$f > /tmp/base_$(basename $f); /usr/bin/python3 -c "
import plistlib,sys
base=plistlib.load(open('/tmp/base_$(basename $f)','rb'))
cand=plistlib.load(open('$f','rb'))
keys=set(base)|set(cand)
for k in sorted(keys):
    b,c=base.get(k,'<MISSING>'),cand.get(k,'<MISSING>')
    if b!=c:
        print('CHANGED',k)
        if isinstance(b,dict) and isinstance(c,dict):
            for kk in sorted(set(b)|set(c)):
                if b.get(kk)!=c.get(kk): print('  ',kk,':',b.get(kk),'=>',c.get(kk))
        else: print('  ',b,'=>',c)
"; done

